import math


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        self._members_set = set(members)
        # Store balances internally in cents (integers) to avoid floating point issues.
        self._balances_cents: dict[str, int] = {m: 0 for m in members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be strictly positive.")

        if payer not in self._members_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            parts = list(self.members)
        else:
            parts = list(participants)

        if not parts:
            raise ValueError("Participants list cannot be empty.")

        for p in parts:
            if p not in self._members_set:
                raise ValueError(f"Participant '{p}' is not a group member.")

        total_cents = round(amount * 100)
        n = len(parts)

        # Requirement 5: Every other participant owes exactly the amount rounded down to the cent.
        # Leftover cents are borne by the payer.
        share_cents = total_cents // n

        for p in parts:
            if p != payer:
                self._balances_cents[p] -= share_cents
                self._balances_cents[payer] += share_cents

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances_cents[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Greedy settlement algorithm producing at most (n - 1) transactions.
        # Maintain current balances in cents.
        debtors: list[list] = []  # [member, -cents] where -cents > 0
        creditors: list[list] = []  # [member, cents] where cents > 0

        for m in self.members:
            cents = self._balances_cents[m]
            if cents < 0:
                debtors.append([m, -cents])
            elif cents > 0:
                creditors.append([m, cents])

        transactions: list[tuple[str, str, float]] = []

        d_idx = 0
        c_idx = 0

        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor, d_cents = debtors[d_idx]
            creditor, c_cents = creditors[c_idx]

            payment_cents = min(d_cents, c_cents)

            # Requirement 3: Never propose a payment smaller than 1.00;
            # debts below 1.00 are written off.
            if payment_cents >= 100:
                transactions.append((debtor, creditor, payment_cents / 100.0))

            debtors[d_idx][1] -= payment_cents
            creditors[c_idx][1] -= payment_cents

            if debtors[d_idx][1] == 0:
                d_idx += 1
            if creditors[c_idx][1] == 0:
                c_idx += 1

        return transactions
